# Code generated by Claude
"""Test helpers for the pouring scene (B3): a kinematic pour of one beaker over the other, and the settling of the scene.

The pour is not a skill (that is B4): the source beaker's free joint is driven along a made-up path each physics step (position and the finite-difference velocity, so the balls feel the wall
move): lift straight up, move over the destination while tilting to 30 degrees, lower the lip to 4 cm above the destination's rim, then tilt at 15 degrees per second (30 per second let the first bead overshoot the 7 cm opening and land 28 cm away) to 120 degrees about the
lip (which stays over the destination's opening) and hold. The source beaker's and the balls' collisions are those of the model; nothing else moves.
"""

import math
import time

import mujoco
import numpy as np

from src.task_beaker_hotplate import spawn_and_settle
from src.task_config import BEAKER_CFG, TASK_CFG

TILT_S = 6.0                                                                  # seconds for the tilt from 30 to 120 degrees (15 degrees per second)
TOTAL_S = 3.5 + TILT_S + 0.5                                                  # lift 1.0, move 1.5, lower 1.0, tilt, hold 0.5


def _smooth(t):
    t = min(max(t, 0.0), 1.0)
    return t ** 3 * (10 - 15 * t + 6 * t ** 2)                                # minimum jerk


def pour_pose(t, lip_rest, lip_over, z_rim, direction, tilt_max=math.radians(120.0)):
    """The source beaker's target (lip position, tilt) at time t of the pour.

    Args:
        t (float): Seconds since the pour began.
        lip_rest (numpy.ndarray): The lip's world position (3,) with the source standing on the bench.
        lip_over (numpy.ndarray): The lip's world position (3,) over the destination at the start of the pour (x, y over the opening; z is not used).
        z_rim (float): World height of the destination's rim, metres.
        direction (int): +1 to tilt towards +x, -1 towards -x.
        tilt_max (float): The final tilt, radians. Defaults to 120 degrees.

    Returns:
        tuple: (lip position (3,), tilt angle phi in radians (the rotation about the y axis is direction * phi)).
    """
    lift = lip_rest + [0, 0, 0.20]
    over_hi = np.array([lip_over[0], lip_over[1], z_rim + 0.14])
    over_lo = np.array([lip_over[0], lip_over[1], z_rim + 0.04])
    if t < 1.0:
        a = _smooth(t / 1.0)
        return lip_rest + a * (lift - lip_rest), 0.0
    if t < 2.5:
        a = _smooth((t - 1.0) / 1.5)
        return lift + a * (over_hi - lift), a * math.radians(30.0)
    if t < 3.5:
        a = _smooth((t - 2.5) / 1.0)
        return over_hi + a * (over_lo - over_hi), math.radians(30.0)
    if t < 3.5 + TILT_S:
        a = _smooth((t - 3.5) / TILT_S)
        return over_lo, math.radians(30.0) + a * (tilt_max - math.radians(30.0))
    return over_lo, tilt_max


def body_pose(lip, phi, direction, beaker_cfg=BEAKER_CFG):
    """The source body's origin and quaternion for a lip position and tilt: the lip is a point of the body (its +direction rim edge)."""
    ell = np.array([direction * beaker_cfg["outer_diameter"] / 2, 0.0, beaker_cfg["height"]])
    a = direction * phi
    R = np.array([[math.cos(a), 0, math.sin(a)], [0, 1, 0], [-math.sin(a), 0, math.cos(a)]])
    return lip - R @ ell, np.array([math.cos(a / 2), 0.0, math.sin(a / 2), 0.0])


def settle(sim, seconds=1.0):
    """Spawns the robot, brings everything to rest, then runs `seconds` more with the robot holding still. Returns the control vector that holds the robot (see spawn_and_settle)."""
    info = spawn_and_settle(sim)
    hold = info["hold"]
    m, d = sim.model, sim.data
    for _ in range(int(seconds / m.opt.timestep)):
        d.ctrl[:] = hold
        mujoco.mj_step(m, d)
    return hold


def run_pour(sim, hold, source, destination, on_step=None, beaker_cfg=BEAKER_CFG):
    """Drives the source beaker through the pour (see the module docstring) while stepping the physics.

    Args:
        sim (RobotSimulator): The simulator with the pouring scene, at rest.
        hold (numpy.ndarray): The control vector that holds the robot.
        source (str): The body name of the beaker that starts full.
        destination (str): The body name of the other one.
        on_step (callable or None): Called after every physics step as on_step(t, step_seconds), t the time since the pour began. Defaults to None.
        beaker_cfg (dict): The beaker configuration. Defaults to BEAKER_CFG.

    Returns:
        dict: "mean_ms" and "max_ms" (per-step wall time of mj_step alone, the maximum over windows of 0.25 s), "steps", "max_contacts", "total_s" (wall time of the whole loop).
    """
    m, d = sim.model, sim.data
    dt = m.opt.timestep
    jid = m.joint(f"{source}_free")
    qa, da = int(jid.qposadr[0]), int(jid.dofadr[0])
    src, dst = d.xpos[m.body(source).id].copy(), d.xpos[m.body(destination).id].copy()
    direction = 1 if dst[0] > src[0] else -1
    lip_rest = src + [direction * beaker_cfg["outer_diameter"] / 2, 0.0, beaker_cfg["height"]]
    lip_over = np.array([dst[0] - direction * 0.02, dst[1], 0.0])
    z_rim = dst[2] + beaker_cfg["height"]
    n = int(TOTAL_S / dt)
    step_t, win, max_c = [], [], 0
    prev_pos, prev_phi = None, 0.0
    wall0 = time.perf_counter()
    for i in range(n):
        t = i * dt
        lip, phi = pour_pose(t + dt, lip_rest, lip_over, z_rim, direction)
        pos, quat = body_pose(lip, phi, direction, beaker_cfg)
        old = d.qpos[qa:qa + 3].copy()
        d.qpos[qa:qa + 3] = pos
        d.qpos[qa + 3:qa + 7] = quat
        d.qvel[da:da + 3] = (pos - old) / dt
        d.qvel[da + 3:da + 6] = [0.0, direction * (phi - prev_phi) / dt, 0.0]
        prev_phi = phi
        d.ctrl[:] = hold
        t0 = time.perf_counter()
        mujoco.mj_step(m, d)
        step_t.append(time.perf_counter() - t0)
        max_c = max(max_c, d.ncon)
        if on_step:
            on_step(t, step_t[-1])
    w = int(0.25 / dt)
    windows = [np.mean(step_t[i:i + w]) for i in range(0, len(step_t) - w + 1, w)]
    return {"mean_ms": 1000 * float(np.mean(step_t)), "max_ms": 1000 * float(max(windows)), "steps": n, "max_contacts": int(max_c), "total_s": time.perf_counter() - wall0}
